def cand_quadrant(inputs,outputs,qname):
 c0,r0={'TR':(5,0),'BL':(0,5),'BR':(5,5)}[qname]
 C=[]
 for i in range(5):
  for j in range(5):
   cells=[r*5+c for r in range(5) for c in range(5) if all(outputs[k][r0+i][c0+j]==inputs[k][r][c] for k in range(len(inputs)))]
   C.append(cells)
 return C
def matchings(C,limit=20):
 order=sorted(range(len(C)),key=lambda x:len(C[x])); out=[]
 def rec(idx,used,m):
  if len(out)>=limit:return
  if idx==len(order):out.append(m.copy());return
  t=order[idx]
  for s in C[t]:
   if s not in used:
    used.add(s);m[t]=s;rec(idx+1,used,m);used.remove(s)
 rec(0,set(),{})
 return out
for q in ['TR','BL','BR']:
 C=cand_quadrant(inputs,outputs,q); ms=matchings(C,1000)
 print(q,'num assignments up to limit',len(ms),'example',ms[:1])
